import{c as t,Q as n,j as s,m as o}from"./chunks/framework.BqPkuuVc.js";const a="/assets/docs-reference-edit-event-extensions-on.CjRKVyQk.png",i="/assets/docs-reference-dashboard-extension-tiles.CX-lKPYh.png",r="/assets/docs-reference-extensions-settings-dialog.BVEIbJmu.png",v=JSON.parse('{"title":"Configuring extensions","description":"","frontmatter":{},"headers":[],"relativePath":"user/advanced/configuring-extensions.md","filePath":"user/advanced/configuring-extensions.md"}'),h={name:"user/advanced/configuring-extensions.md"};function l(d,e,g,c,p,u){return n(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="configuring-extensions" tabindex="-1">Configuring extensions <a class="header-anchor" href="#configuring-extensions" aria-label="Permalink to &quot;Configuring extensions&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers setting up an installed extension for their events.</p><p>An extension can have settings at two levels: settings for this computer, shared by every event, and settings for one event. This page covers both, and switching an extension on for an event.</p><h2 id="using-an-extension-in-an-event" tabindex="-1">Using an extension in an event <a class="header-anchor" href="#using-an-extension-in-an-event" aria-label="Permalink to &quot;Using an extension in an event&quot;">​</a></h2><p>An installed extension does nothing in an event until the event switches it on:</p><ol><li>Open the event and click <strong><a href="./../event-setup/create-event#editing-event-details">Event details</a></strong>.</li><li>Go to the <strong>Extensions</strong> tab. Every installed extension is listed with a switch.</li><li>Switch on the ones this event should use. An extension with per-event settings shows them as soon as it&#39;s on.</li><li>Click <strong>Save</strong>.</li></ol><p><img src="'+a+'" alt="Event details → Extensions: Late entries sheet switched on with its per-event settings (Sheet name, Show only paid entries) below it, and Bus count switched off"></p><p>Its tile then appears on the event&#39;s dashboard. Like any tile, you can hide it or move it with <strong>Edit dashboard</strong>. See <a href="./../running-the-event/dashboard">The event dashboard</a>.</p><p><img src="'+i+'" alt="The dashboard with two extension tiles below the built-in ones: Late entries, a list with its total, and Buses, a single number"></p><p>A tile shows either one big number with a caption, or a list with <strong>Total:</strong> and its count at the top right (<em>No entries yet</em> while the list is empty). If an extension&#39;s script fails, its tile says <strong>Failed to load</strong> instead; the rest of the dashboard is unaffected.</p><p>Some tiles only work while the event is running, for example one that fetches entries from elsewhere on the day. Before the event starts and after it finishes, such a tile shows a placeholder and fetches nothing.</p><p>An extension keeps working on every page of the event, not only while the dashboard is on screen: one that fetches entries carries on while you&#39;re on <strong>Download card</strong> or <strong>Competitors</strong>. It runs in each browser that has the event open in Manager, and stops when that browser closes the event or the computer sleeps. The tile shows what it has done whenever you come back to the dashboard.</p><h3 id="when-an-extension-doesn-t-seem-to-do-anything" tabindex="-1">When an extension doesn&#39;t seem to do anything <a class="header-anchor" href="#when-an-extension-doesn-t-seem-to-do-anything" aria-label="Permalink to &quot;When an extension doesn&#39;t seem to do anything&quot;">​</a></h3><p>An extension writes notes to Manager&#39;s log as it works: when it starts and stops, and whatever its author chose to report (an entries extension, for instance, what each check of the spreadsheet found and anyone it couldn&#39;t enter). Each line starts with <code>Extension</code> and the extension&#39;s name. If a tile stays at 0 when you expected something, look in that day&#39;s log, or send it to whoever wrote the extension. <a href="./../reference/troubleshooting#where-the-logs-are">Troubleshooting</a> says where the logs are.</p><h2 id="the-two-levels-of-settings" tabindex="-1">The two levels of settings <a class="header-anchor" href="#the-two-levels-of-settings" aria-label="Permalink to &quot;The two levels of settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Level</th><th>Where</th><th>Applies to</th><th>Typical use</th></tr></thead><tbody><tr><td><strong>This computer</strong></td><td>The <strong>Extensions</strong> page: the extension&#39;s settings button</td><td>Every event on this computer</td><td>An account, a key, an address the extension connects to</td></tr><tr><td><strong>This event</strong></td><td><strong>Event details → Extensions</strong>, under the extension&#39;s switch</td><td>This event only</td><td>Which spreadsheet, which classes, a colour for this event</td></tr></tbody></table><p>Which settings an extension has, at either level, is up to whoever wrote it. Each is a switch, a text box, a number or a choice of colour, with the extension&#39;s own label.</p><h3 id="settings-for-this-computer" tabindex="-1">Settings for this computer <a class="header-anchor" href="#settings-for-this-computer" aria-label="Permalink to &quot;Settings for this computer&quot;">​</a></h3><p>On the <strong>Extensions</strong> page, click the extension&#39;s settings button (it only has one if the extension has settings for this computer), change them, and click <strong>Save</strong> (<em>Settings saved.</em>). They apply to every event straight away; reload any browser that has an event open to be sure the extension has picked them up.</p><p><img src="'+r+'" alt="The settings dialog for Late entries sheet on the Extensions page: Spreadsheet API key and Refresh every (seconds), with Cancel and Save"></p><h3 id="settings-for-an-event" tabindex="-1">Settings for an event <a class="header-anchor" href="#settings-for-an-event" aria-label="Permalink to &quot;Settings for an event&quot;">​</a></h3><p>In <strong>Event details → Extensions</strong>, change the fields under the extension&#39;s switch, then <strong>Save</strong> the event details. They&#39;re saved with the event, so they go with it in a backup and when it&#39;s moved to another computer, unlike the settings for this computer.</p><h2 id="copying-settings-to-another-event" tabindex="-1">Copying settings to another event <a class="header-anchor" href="#copying-settings-to-another-event" aria-label="Permalink to &quot;Copying settings to another event&quot;">​</a></h2><p>There&#39;s no copy button. A <a href="./../event-setup/create-event#duplicating-an-event">duplicated event</a> keeps its extensions switched on with the same settings; otherwise, switch the extension on in the new event and fill its settings in again.</p><h2 id="getting-back-to-the-defaults" tabindex="-1">Getting back to the defaults <a class="header-anchor" href="#getting-back-to-the-defaults" aria-label="Permalink to &quot;Getting back to the defaults&quot;">​</a></h2><p>There&#39;s no reset button, and settings are kept on purpose:</p><ul><li><strong>An event&#39;s settings</strong> start from the extension&#39;s own defaults the first time you switch it on. Switching it off and on again keeps what you had set.</li><li><strong>Settings for this computer</strong> are kept when you remove the extension, so installing it again, or a newer version, brings them back.</li></ul><p>To go back to the defaults, set each field back by hand.</p><h2 id="what-a-tile-remembers-by-itself" tabindex="-1">What a tile remembers by itself <a class="header-anchor" href="#what-a-tile-remembers-by-itself" aria-label="Permalink to &quot;What a tile remembers by itself&quot;">​</a></h2><p>Separately from its settings, a tile may remember things as you use it — what you last picked in it, say. That memory is kept in the browser of the computer you&#39;re at, for that event only. It isn&#39;t shared with other computers, doesn&#39;t go into a backup, and is lost if that browser&#39;s site data is cleared.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./installing-extensions">Installing extensions</a></li><li><a href="./../running-the-event/dashboard">The event dashboard</a></li><li><a href="./../event-setup/create-event#extensions">Creating an event</a></li></ul>',32)])])}const m=t(h,[["render",l]]);export{v as __pageData,m as default};
